int forge_app::run_ui(int argc, char** argv) {
  (void)argc;
  // A cached language pack is applied before the window exists, so there is no flash of English.
  set_refresh_hook([] { g_surface.refresh_all(); });
  start_gui_language();
  g_surface.set_state(StateId::s0, Text("Press the button"));
  GtkApplication* app = gtk_application_new("dev.forge.steps", G_APPLICATION_DEFAULT_FLAGS);
  g_signal_connect(app, "activate", G_CALLBACK(activate), nullptr);
  // The command line was already handled by forge: GTK gets only the program name.
  const int status = g_application_run(G_APPLICATION(app), 1, argv);
  g_object_unref(app);
  return status;
}
